--
-- Estructura de tabla para la tabla `lecturas`
--

CREATE TABLE `lecturas` (
  `id` bigint(20) NOT NULL,
  `arduino_id` int(11) NOT NULL,
  `tipo_sensor` enum('presion','flujo') NOT NULL COMMENT 'Tipo de sensor',
